import * as PIXI from 'pixi.js';

export class SliderControl extends PIXI.Sprite {
    public controlIndex: number;
    private enabledTexture: PIXI.Texture;
    private disabledTexture: PIXI.Texture;
    private enabled: boolean;
    private changeSlideCallback: (index: number) => void;
    private transitionSlideInCallback: () => void;

    constructor(textures: { enabled: PIXI.Texture, disabled: PIXI.Texture },
        enabled: boolean,
        changeSlideCallback: (index: number) => void,
        transitionSlideInCallback: () => void,
        controlIndex: number) {
        super(enabled ? textures.enabled : textures.disabled);

        this.enabledTexture = textures.enabled;
        this.disabledTexture = textures.disabled;
        this.enabled = enabled;
        this.changeSlideCallback = changeSlideCallback;
        this.transitionSlideInCallback = transitionSlideInCallback;
        this.controlIndex = controlIndex;

        this.interactive = true;
        this.cursor = this.enabled ? 'pointer' : undefined;
        this.on('pointerup', this.onPointerUp);
    }

    public handleOrientationChange(controlAreaHeight: number): void {
        this.width = this.height = controlAreaHeight * 0.8;

        this.position.x = (this.width * 1.2) * this.controlIndex;
    }

    public enable(): void {
        this.texture = this.enabledTexture;
        this.enabled = true;
        this.cursor = undefined;
    }

    public disable(): void {
        this.texture = this.disabledTexture;
        this.enabled = false;
        this.cursor = 'pointer';
    }

    private onPointerUp(): void {
        if (this.enabled) { return; }

        this.enable();
        this.changeSlideCallback(this.controlIndex);
        this.transitionSlideInCallback();
    }
}
